            .then(lambda variant: ChannelContext(node=variant, channel_slug=None))
        )

    @staticmethod
    def resolve_warehouse(root, info: ResolveInfo):
        _, stock = root
        return WarehouseByIdLoader(info.context).load(stock.warehouse_id)


